before_layer_change_gcode:
;BEFORE_LAYER_CHANGE
;[layer_z]
{if layer_num != 0}
G92 E0
{endif}
{if layer_num <= 0}
G91
G1 Z+10 F1200
G90
{endif}

change_filament_gcode:
;CHANGE_FILAMENT - Start
;Layer#=[layer_num] - Z=[layer_z]
{if layer_z >first_layer_height}
G91
G1 Z+2 F1200
G90
{endif}
{if layer_num != -1 || next_extruder != 0}
  Tool{next_extruder}
{endif}
; <----
G1 Z[layer_z] F1200
{if layer_num == -1 || layer_num == 0}
  M109 S[first_layer_temperature[next_extruder]] T[next_extruder]
{else}
  M104 S[temperature[next_extruder]] T[next_extruder]
{endif}
; ---->
M83
;Layer#=[layer_num] - Z=[layer_z]
LOG_EXTR
;CHANGE_FILAMENT - End
